-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Polypharmacy & Beers Criteria — high-risk drug classes in elderly - Part 1 (1-100)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-polypharmacy' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-polypharmacy not found.';
    END IF;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

END $$;
COMMIT;